	first := manager.CXProgramAlloc()
	manager.CXProgramGet(first).Version = int64(11)
	second := manager.CXProgramAlloc()
	manager.CXProgramGet(second).Version = int64(22)
	CXProgramMngTestCheck(t, &manager, "two allocs", 2, 2)
	if objmodel.GidTypeTag(int64(first)) != CXProgramGidTypeTag || objmodel.GidGeneration(int64(first)) != objmodel.GidGenerationFirst {
		t.Fatalf("first Gid %#x has the wrong tag or generation", int64(first))
	}
	if int(manager.CXProgramGet(first).Version) != 11 || int(manager.CXProgramGet(second).Version) != 22 {
		t.Fatal("Get does not return the allocated objects")
	}

	manager.CXProgramRelease(first)
	CXProgramMngTestCheck(t, &manager, "release", 1, 2)
	third := manager.CXProgramAlloc()
	CXProgramMngTestCheck(t, &manager, "reuse", 2, 2)
	if objmodel.GidIndex(int64(third)) != objmodel.GidIndex(int64(first)) {
		t.Fatal("Alloc did not reuse the released slot")
	}
	if objmodel.GidGeneration(int64(third)) != objmodel.GidGeneration(int64(first))+1 {
		t.Fatalf("generation %d after one release, want %d", objmodel.GidGeneration(int64(third)), objmodel.GidGeneration(int64(first))+1)
	}
